import math

def check(n):
    if n < 0:
        return False

    denominator = 2 * n - 1
    if denominator == 0:
        # Should not happen for integer n
        return False

    numerator = 3 * (math.factorial(n + 2) + 1)

    # Check if numerator is divisible by denominator
    if numerator % denominator == 0:
        print(f"n={n}: Integer. Value = {numerator // denominator}")
        return True
    else:
        print(f"n={n}: Not integer. Numerator={numerator}, Denominator={denominator}")
        return False

print("--- Checking n=0 to n=10 ---")
for n in range(11):
    check(n)

